t.script:
(function () {
  "use strict";
  function $(s,r){return (r||document).querySelector(s);}
  function $v(id,d){var e=$("#"+id); return e?e.value:d;}

  function readAsDataURL(file){
    return new Promise(function(res,rej){
      var r=new FileReader(); r.onload=function(){res(r.result);}; r.onerror=rej; r.readAsDataURL(file);
    });
  }
  function loadImage(src){
    return new Promise(function(res,rej){
      var im=new Image(); im.onload=function(){res(im);}; im.onerror=rej; im.src=src;
    });
  }

  function applyTransform(){
    var logo=$("#spw_logo_preview"), base=$("#spw_product_img"); if(!logo||!base) return;
    var size=parseInt($v("spw_size","100"),10), px=parseInt($v("spw_pos_x","0"),10), py=parseInt($v("spw_pos_y","10"),10), rot=parseInt($v("spw_rotation","0"),10);
    var bw=base.clientWidth, bh=base.clientHeight, left=bw*(0.5+px/100), top=bh*(0.6+py/100);
    logo.style.position="absolute"; logo.style.left=left+"px"; logo.style.top=top+"px";
    logo.style.transform="translate(-50%,-50%) rotate("+rot+"deg)"; logo.style.width=size+"px";
    logo.classList.remove("d-none");
  }

  async function renderPNGDataURL(){
    var baseEl=$("#spw-base-img");
    var baseSrc=(baseEl && baseEl.getAttribute("src")) || $v("spw_img_src","") || ($("#spw_product_img")||{}).getAttribute("src");
    if(!baseSrc) throw new Error("Sin imagen base");
    var baseIm=await loadImage(baseSrc);
    var c=document.createElement("canvas"), ctx=c.getContext("2d");
    c.width=baseIm.naturalWidth||baseIm.width; c.height=baseIm.naturalHeight||baseIm.height;
    ctx.drawImage(baseIm,0,0,c.width,c.height);

    var logo=$("#spw_logo_preview");
    if(logo && logo.src){
      var base=$("#spw_product_img"), bw=base.clientWidth, bh=base.clientHeight;
      var br=base.getBoundingClientRect(), lr=logo.getBoundingClientRect();
      var cx=((lr.left+lr.width/2)-br.left)/bw*c.width, cy=((lr.top+lr.height/2)-br.top)/bh*c.height;
      var drawW=(lr.width/bw)*c.width, li=await loadImage(logo.src);
      var ratio=(li.naturalHeight||li.height)/(li.naturalWidth||li.width), drawH=drawW*ratio;
      var rot=(parseInt($v("spw_rotation","0"),10)*Math.PI)/180;
      ctx.save(); ctx.translate(cx,cy); ctx.rotate(rot); ctx.drawImage(li,-drawW/2,-drawH/2,drawW,drawH); ctx.restore();
    }
    return c.toDataURL("image/png");
  }

  // Botón descargar (en iOS abre en pestaña para guardar)
  async function onDownload(){
    try{
      var dataUrl=await renderPNGDataURL();
      var a=document.createElement("a"); a.href=dataUrl; a.download="personalizacion.png";
      if(typeof a.download==="undefined" || /iPad|iPhone|iPod/i.test(navigator.userAgent)){ window.open(dataUrl,"_blank"); }
      else { document.body.appendChild(a); a.click(); a.remove(); }
    }catch(_e){ alert("No se pudo generar el PNG"); }
  }

  // Añadir al carrito por endpoint nativo + guardar PNG en sessionStorage
  async function onAddToCart(){
    var variantId=($v("spw_variant_id","")||"").trim(); if(!variantId){ alert("Falta la variante"); return; }
    var qty=parseInt($v("spw_qty","1"),10)||1;
    try{ sessionStorage.setItem('spw_last_png', await renderPNGDataURL()); }catch(_e){}
    var fd=new FormData(); fd.append('product_id', variantId); fd.append('add_qty', qty); fd.append('express','1');
    try{ await fetch('/shop/cart/update',{method:'POST', body:fd, credentials:'include'}); }catch(_e){}
    window.location='/shop/cart';
  }

  function init(){
    var input=document.getElementById("spw_logo_input"), logo=document.getElementById("spw_logo_preview");
    if(input){ input.addEventListener("change", async function(ev){ var f=ev.target.files && ev.target.files[0]; if(!f) return; logo.src=await readAsDataURL(f); applyTransform(); }); }
    ["spw_size","spw_pos_x","spw_pos_y","spw_rotation"].forEach(function(id){ var el=document.getElementById(id); if(el) el.addEventListener("input", applyTransform); });
    window.spwReset=function(){ document.getElementById("spw_size").value=100; document.getElementById("spw_pos_x").value=0; document.getElementById("spw_pos_y").value=10; document.getElementById("spw_rotation").value=0; applyTransform(); };
    var dl=document.getElementById("spw_download_png"); if(dl) dl.addEventListener("click", onDownload);
    var add=document.getElementById("spw_add_to_cart"); if(add) add.addEventListener("click", onAddToCart);
    applyTransform();
  }

  if(document.readyState==="loading"){ document.addEventListener("DOMContentLoaded", init); } else { init(); }
})();

xpath.script:
//
(function(){
  function inject(){
    if(!/\/shop\/cart/.test(location.pathname)) return;
    var dataUrl = sessionStorage.getItem('spw_last_png'); if(!dataUrl) return;
    var container = document.querySelector('.td-product_name') || document.querySelector('.css_description') || document.querySelector('.oe_cart');
    if(!container || container.querySelector('.spw-preview')) return;
    var img=document.createElement('img'); img.src=dataUrl; img.className='spw-preview';
    img.style.maxWidth='180px'; img.style.border='1px solid #eee'; img.style.marginTop='8px';
    container.appendChild(img);
  }
  if(document.readyState==='loading'){ document.addEventListener('DOMContentLoaded', function(){ inject(); setTimeout(inject,600); }); } else { inject(); setTimeout(inject,600); }
})();
//
